<?php use app\services\Ui;use app\models\User;use yii\helpers\Html;$this->title='Tasdiqlash bosqichlari'; ?>
<div class="page-heading"><div><span class="eyebrow">ISH JARAYONI</span><h1>Tasdiqlash bosqichlari</h1><p>Bo‘sh nomli bosqichlar olinmaydi. Oxirgi bosqich yakuniy hisoblanadi.</p></div></div><section class="card"><div class="alert info">Har ariza yuborilganda marshrutning o‘z nusxasini oladi. Sozlamani o‘zgartirish avvalgi arizalarni boshqa bosqichga ko‘chirmaydi.</div><?= Html::beginForm(['admin/route'],'post') ?><?php for($i=0;$i<5;$i++):$step=$steps[$i]??null; ?><div class="route-edit"><span class="rank"><?= $i+1 ?></span><?= Ui::input('Bosqich nomi','names['.$i.']',$step['name']??'') ?><fieldset><legend>Tekshiruvchi rollari</legend><?php foreach(['head','faculty','expert','admin','superadmin'] as $role): ?><label class="check"><?= Html::checkbox('roles['.$i.'][]',in_array($role,json_decode($step['roles']??'[]',true),true),['value'=>$role]) ?> <?= Ui::h(User::ROLES[$role]) ?></label><?php endforeach ?></fieldset></div><?php endfor ?><button class="button">Marshrutni saqlash</button><?= Html::endForm() ?></section>
